-- v1.33.0: no escrow anywhere in the Terms, policies, Help Center or tips while escrow services are paused (owner, 2026-11-18).
-- The previous texts are kept in guides_escrow_backup so they can be restored when the services come back.
create table if not exists public.guides_escrow_backup as select * from public.guides where false;
alter table public.guides_escrow_backup enable row level security;
insert into public.guides_escrow_backup select * from public.guides where slug in ('terms', 'refunds', 'aml', 'about', 'help-bills-how', 'help-market-buy', 'help-market-flash', 'help-start-verify', 'help-start-what', 'tip-flash', 'tip-kyc', 'tip-market', 'p2p-proof', 'tip-escrow', 'tip-p2p-release', 'tip-p2p-appeal') and not exists (select 1 from public.guides_escrow_backup);

update public.guides set title = 'Luda Terms & Conditions', intro = 'These terms are an agreement between you and Luda Digital Systems Limited ("Luda", "we"), the company that runs the Luda app and useluda.com. By creating an account or using Luda you agree to them. If we change them, we will ask you to agree again before you continue.', steps = '[{"title": "1. Who we are", "body": "Luda is run by Luda Digital Systems Limited. It is an app for students and people from Africa living in North Cyprus. It offers a wallet in Naira and Turkish lira, currency conversion, bill payment help, bus tickets, marketplace listings, Flash help requests, community posts and university tools."}, {"title": "2. Your account", "body": "You must be at least 18 and give true details. One person may have only one Luda account. We check every verified ID document and face against all other accounts, so a second account can''t be verified. Extra accounts may be frozen or closed, and rewards, prizes and referral bonuses gained through them will be removed. Keep your password and PIN private; you are responsible for activity on your account. Tell us at once if you think someone else has used it. We may ask you to verify your identity (ID document and selfie) before you can withdraw, send money, sell on the Market or help on Flash."}, {"title": "3. Your wallet and money", "body": "Money in your Luda wallet is recorded by Luda''s server ledger. Top-ups are processed by our payment partners (such as Paystack and Flutterwave) and withdrawals go only to a bank account in your verified name. Balances, fees and exchange rates shown in the app are set by our server at the moment of each action. We may delay or hold a transaction to check it for fraud, errors or legal reasons, and we may correct mistakes in the ledger."}, {"title": "4. Fees", "body": "Fees are shown in the app (Wallet, Fees), on the Fees page (useluda.com/fees) and on every confirmation screen before you approve. Payment partners may add their own fees. We may change fees for future transactions; the fee shown when you confirm is the one that applies."}, {"title": "5. Bills, Market and Flash", "body": "Bill payments are made by the Luda team on the official site and a receipt is added; if we can''t pay a bill we refund it. Market listings and Flash requests connect people: buyers pay sellers, and people who post a request pay their helper, directly between themselves. Luda does not take or hold those payments and is not part of that deal. Meet in safe places, check before you pay, and report anything suspicious. Sellers and helpers are responsible for what they offer."}, {"title": "6. Rules everyone follows", "body": "No fraud, fake accounts, money laundering, scams, harassment, hate, adult content, or asking for money in advance for something you haven''t delivered. Posts and messages are checked and limited to keep Luda safe. We may remove content, limit features, freeze or close accounts that break these rules, and report illegal activity to the authorities."}, {"title": "7. Rewards", "body": "XP, points, prizes and referral bonuses are worked out by Luda''s server from real activity and may have monthly limits. Cash prizes need a verified identity. Rewards gained by cheating, multiple accounts or fake referrals will be removed."}, {"title": "8. Privacy", "body": "We keep the data needed to run Luda and keep it safe: your profile, identity check results, transactions, and messages in support cases. Identity checks are done by our partner Didit. We don''t sell your data. Support photos are visible only to you and the Luda team."}, {"title": "9. Information in the app", "body": "University dates, bus times, places and guides are provided to help you and may change; always confirm important dates with the official source. Luda is not your university, bank, landlord or bus company."}, {"title": "10. Limits of our responsibility", "body": "We work hard to keep Luda available and correct, but we can''t promise it will never be interrupted. We are not responsible for losses caused by deals between users (such as Market or Flash payments), by your bank or payment partner, or by you sharing your PIN or password. Nothing in these terms removes rights you have by law."}, {"title": "11. Closing your account", "body": "You can ask the Luda team to close your account at any time; we will help you withdraw your balance first. We may close or freeze accounts that break these terms."}, {"title": "12. Refunds, cancellations and chargebacks", "body": "When and how money is returned is explained in our Refund & cancellation policy (useluda.com/refunds), which is part of these terms. If something goes wrong with a payment, contact us first: we answer within 2 business days. If you dispute a card or bank payment with your bank (a chargeback) for money you already used in Luda, we may hold your account while we look into it and recover the amount from your wallet."}, {"title": "13. Identity checks and anti-money-laundering", "body": "We follow our AML & KYC policy (useluda.com/aml). We may ask for more information, limit, hold or refuse a transaction, and report suspicious activity to the authorities where the law requires it."}, {"title": "14. Changes and contact", "body": "We may update these terms; the version and date are shown here, and you will be asked to agree to important changes. Questions or complaints: Help, then Message us in the app, or email support@useluda.com. Company details are on useluda.com/about."}]'::jsonb, version = version + 1, updated_at = now(), updated_by = 'luda' where slug = 'terms';
update public.guides set title = 'Refund & cancellation policy', intro = 'This policy explains when and how Luda Digital Systems Limited returns money to you. Refunds go back to your Luda wallet unless stated otherwise. To ask for a refund, open Help, then Message us in the app, or email support@useluda.com with your reference.', steps = '[{"title": "Top-ups", "body": "Your wallet is credited when our payment partner (Paystack or Flutterwave) confirms the payment. If you were charged but your wallet was not credited, we check with the partner automatically within 48 hours. If the payment is confirmed we credit it; if not, the partner returns the money to your card or bank account, usually within 5–10 business days. Money already credited to your wallet is not sent back to the card; you can withdraw it to your own bank account instead."}, {"title": "Withdrawals", "body": "If a withdrawal fails or cannot be paid, the full amount and the withdrawal fee go back to your wallet. A withdrawal that has reached your bank cannot be cancelled."}, {"title": "Currency conversion", "body": "A conversion is final once you confirm it at the rate shown. If the rate changes before you confirm, you see the new rate first."}, {"title": "Bus tickets", "body": "Contact us before the travel date to cancel an unused ticket; it is refunded to your wallet. Used tickets, and tickets for a date that has passed, are not refunded."}, {"title": "Bills and rent", "body": "If the Luda team cannot pay your bill, the amount and the fee are refunded to your wallet with the reason. Once a bill is paid and the receipt is added, Luda cannot take it back; mistakes in the details you typed (like a wrong meter number) must be fixed with the biller."}, {"title": "Market and Flash", "body": "Luda doesn''t take payments for Market items or Flash jobs: they are paid directly between people, so Luda can''t refund them. Settle problems with the other person, and report scams to us so we can act on the account."}, {"title": "Fees", "body": "A fee is refunded when the transaction it belongs to is refunded in full (for example a failed withdrawal or an unpaid bill). Fees charged by payment partners at top-up are set by the partner."}, {"title": "Chargebacks", "body": "Please contact us before disputing a payment with your bank. If you open a chargeback for a top-up you already used in Luda, we may hold your account while we look into it and recover the amount from your wallet."}, {"title": "How long it takes", "body": "We answer refund requests within 2 business days. Refunds to your Luda wallet are instant once approved. Refunds to a card or bank account depend on the payment partner and your bank."}]'::jsonb, updated_at = now(), updated_by = 'luda' where slug = 'refunds';
update public.guides set title = 'AML & KYC policy', intro = 'Luda Digital Systems Limited works to stop fraud, money laundering and the financing of crime on Luda. This policy explains the checks we do and what we may do when something looks wrong.', steps = '[{"title": "Knowing our customers", "body": "Every account needs a real name, an email address and a payment PIN. Before you can withdraw, send money, sell on the Market or help on Flash, you must verify your identity with an official ID document and a live selfie. Checks are done by our partner Didit, or by the Luda team for documents sent to us."}, {"title": "One account per person", "body": "Each person may have only one Luda account. ID documents and faces are compared with other verified accounts, and extra accounts are frozen."}, {"title": "Limits", "body": "Accounts that are not verified have low top-up and balance limits. Verified accounts have higher daily limits for top-ups, withdrawals, sending and conversion. Lira bought with Naira is limited per day and can be spent in Luda but not sent to other people."}, {"title": "Withdrawals", "body": "Money can only be withdrawn to a bank account in the same name as your verified ID. After a password or PIN reset, withdrawals and sending are paused for 24 hours."}, {"title": "Monitoring", "body": "Our server records every movement of money in a ledger. We watch for unusual activity, such as many accounts on one device, payments that don''t match, or patterns linked to scams."}, {"title": "What we may do", "body": "We may ask for more information or documents, delay or refuse a transaction, limit or freeze an account, and close accounts used for fraud. Where the law requires it, we report suspicious activity to the authorities, and we may not be allowed to tell you."}, {"title": "Not allowed on Luda", "body": "Money laundering, fraud, scams, using someone else''s identity or account, buying or selling accounts, paying for illegal goods or services, and asking people to pay outside Luda."}, {"title": "Records", "body": "We keep identity check results and transaction records for as long as the law requires, including after an account is closed."}, {"title": "Reporting a concern", "body": "To report suspicious activity, use Report a scam in Help, or email support@useluda.com."}]'::jsonb, updated_at = now(), updated_by = 'luda' where slug = 'aml';
update public.guides set title = 'About Luda', intro = 'Luda is an all-in-one app for African students and families living in North Cyprus. It is run by Luda Digital Systems Limited.', steps = '[{"title": "What we offer", "body": "• A wallet in Naira (₦) and Turkish lira (₺): top up by card or bank transfer through Paystack or Flutterwave, and withdraw to your own bank account.\n• Naira ⇄ lira conversion at a rate shown before you confirm.\n• Bill payments (electricity, water, gas, internet, mobile, rent), paid by the Luda team on the official sites.\n• Girne ⇄ Lefkoşa bus tickets.\n• Marketplace listings and Flash help requests, paid directly between people.\n• Free community, housing, jobs and university tools."}, {"title": "Prices", "body": "Creating an account is free and there are no monthly fees. Each paid service has a small fee that you see before you confirm; the full list is on the Fees page. Bus tickets cost ₺250 single and ₺450 return."}, {"title": "How you pay", "body": "Top-ups are paid by card or bank transfer through Paystack, or through Flutterwave for other currencies. After that you pay for everything in the app from your Luda wallet, and you get a receipt for every payment."}, {"title": "When you get it", "body": "Wallet actions happen instantly. Bills are paid within the time shown when you pay, usually within 2 hours during working hours. Bus tickets appear in the app with a QR code for the driver. Market items and Flash jobs are arranged between the people involved."}, {"title": "Contact us", "body": "Help with your account or a payment: support@useluda.com\nGeneral questions: hello@useluda.com\nIn the app: Help, then Message us\nWe answer within 2 business days."}, {"title": "Company", "body": "Luda Digital Systems Limited"}]'::jsonb, updated_at = now(), updated_by = 'luda' where slug = 'about';
update public.guides set title = 'How does bill pay work?', intro = 'Choose the bill, type the details exactly as they appear on your bill and confirm. You pay the amount plus the service fee (₺10 up to ₺1,000, ₺20 above) from your Lira wallet. The Luda team pays it on the official site and uploads the receipt, usually within 2 hours between 09:00 and 19:00. If we can''t pay it, you get everything back.', updated_at = now(), updated_by = 'luda' where slug = 'help-bills-how';
update public.guides set title = 'How do I buy on Market?', intro = 'Market shows items from people near you. Message the seller on WhatsApp from the listing, meet in a safe public place, check the item and pay the seller directly. Luda doesn''t take payments for Market items. Never pay before you have seen the item, and report a listing that looks like a scam.', updated_at = now(), updated_by = 'luda' where slug = 'help-market-buy';
update public.guides set title = 'How does Flash work?', intro = 'Post what you need with a starting budget, photos or a video. Verified helpers chat with you and send their own price. When you accept a price, you pay the helper in cash when the job is done. The helper adds photos when they finish; tap ''Job done'' to close the request. If something goes wrong, report a problem from the request.', updated_at = now(), updated_by = 'luda' where slug = 'help-market-flash';
update public.guides set title = 'Why do I need to verify my ID?', intro = 'You can look around without an ID check. Verifying your ID (a photo of your document and a quick selfie) unlocks withdrawals, sending money, selling on Market, helping on Flash and cash prizes. It keeps scammers and fake accounts out. You get 2 tries a day.', updated_at = now(), updated_by = 'luda' where slug = 'help-start-verify';
update public.guides set title = 'What can I do with Luda?', intro = 'Luda is one app for life in North Cyprus: a Naira and Lira wallet, Girne ⇄ Lefkoşa bus tickets, bills paid for you by the Luda team, Market listings, Flash help requests, rooms and jobs, university dates and places near you.', updated_at = now(), updated_by = 'luda' where slug = 'help-start-what';
update public.guides set title = 'How Flash jobs work', intro = 'Post what you need with your starting budget. Helpers chat with you and send their own price. When you accept a price, you pay the helper in cash once the job is done. The helper finishes and adds photos; then tap ''Job done''.', updated_at = now(), updated_by = 'luda' where slug = 'tip-flash';
update public.guides set title = 'Why we check your ID', intro = 'One real person, one account. Checking your ID (document + selfie) keeps scammers out, and unlocks withdrawals, sending money, selling, Flash jobs and cash prizes. Your ID is checked by our partner Didit; you get 2 tries a day.', updated_at = now(), updated_by = 'luda' where slug = 'tip-kyc';
update public.guides set title = 'Buying safely on Market', intro = 'Luda doesn''t take payments for Market items: you pay the seller directly. Meet in a public place, check the item before you pay, and never send money in advance.', updated_at = now(), updated_by = 'luda' where slug = 'tip-market';
